+// ---------- Checkout wizard (payment-method-captured order) ------------------
+//
+// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
+// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
+// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
+// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
+// REFUSES to provision unless the account has a way to bill the renewal (a saved
+// card OR a wallet balance that already covers one renewal), it is idempotent
+// against double-submit, and it then delegates the ACTUAL charge to the audited
+// `orderHostingAccount` above — one debit path, never a second one.
+//
+// displayed === charged === renewed: this action computes NO price of its own for
+// the debit. The wallet debit + the first-month-free reserve→confirm→release
+// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
+// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
+// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
+
+export type HostingOrderInput = {
+  planId: string;
+  /** Empty/omitted => free temporary `<username>.nxeon.cloud` subdomain. */
+  domain?: string;
+  termMonths?: number;
+  /** Optional catalog app to auto-install after the account provisions. */
+  appSlug?: string;
+  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
+  idempotencyKey: string;
+};
+
+export type HostingOrderResult =
+  | { ok: true; accountId: string }
+  | { error: string }
+  /** No renewal-capable payment method yet — the wizard must capture a card first. */
+  | { needCard: true; renewalCents: number };
+
+/**
+ * The full-price single renewal of a plan/term — the gate threshold, identical to
+ * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
+ */
+async function hostingRenewalCents(plan: { priceCents: number }, term: number): Promise<number> {
+  const annualPct = await annualDiscountPct();
+  return termPriceCents(plan.priceCents, term, annualPct);
+}
+
+/** Place a hosting order from the checkout wizard. See the block comment above. */
+export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
+  const user = await requireUser();
+  await assertNotImpersonating();
+  const unverified = await emailVerificationError(user);
+  if (unverified) return { error: unverified };
+
+  const key = String(input.idempotencyKey ?? "").trim();
+  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
+
+  const term = normalizeProductTerm(input.termMonths);
+  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
+  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
+
+  // RENEWAL-METHOD GATE — the core fix. Never provision a paid product with no way
+  // to bill the renewal. A saved card (charged off-session by the renewal sweep) OR
+  // a wallet already holding one renewal's worth qualifies; otherwise the wizard
+  // sends the customer to Stripe to capture a card (which also handles the $0-today
+  // case, where no card would otherwise be collected).
+  const renewalCents = await hostingRenewalCents(plan, term);
+  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
+    return { needCard: true, renewalCents };
+  }
+
+  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
+  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
+  // token table. A rapid resubmit or a network retry with the same key can't create
+  // a second account or take a second debit.
+  const sessionKey = `hostorder:${key}`;
+  try {
+    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
+  } catch (e) {
+    if (isUniqueViolation(e)) {
+      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
+      // A completed prior attempt: replay its result (no second charge).
+      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
+      // A failed prior attempt: clear it so an explicit retry can proceed.
+      if (prior?.status === "FAILED") {
+        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
+      } else {
+        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
+        return { error: "That order is already being placed — check your hosting accounts in a moment." };
+      }
+      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
+      try {
+        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
+      } catch {
+        return { error: "That order is already being placed — check your hosting accounts in a moment." };
+      }
+    } else {
+      throw e;
+    }
+  }
+
+  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
+  // the free temporary subdomain. All money movement, the first-month-free atomic
+  // claim and the hostname claim happen inside orderHostingAccount's transaction.
+  const res = await orderHostingAccount(input.planId, input.domain ?? "", term);
+  if (res.error || !res.accountId) {
+    await db.fulfilledSession
+      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
+      .catch(() => {});
+    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
+  }
+  await db.fulfilledSession
+    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
+    .catch(() => {});
+
+  // Optional one-click app install: queue it now so the worker installs it the
+  // moment the account finishes provisioning. Best-effort — a bad slug never voids
+  // the (already-charged) order; the customer can install from the panel later.
+  const slug = String(input.appSlug ?? "").trim();
+  if (slug) {
+    try {
+      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
+    } catch {
+      /* non-fatal: the account is created and charged; the app can be installed later */
+    }
+  }
+
+  revalidatePath("/dashboard/hosting");
+  return { ok: true, accountId: res.accountId };
+}
+
+/**
+ * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
+ * but without the ACTIVE gate — the task waits in the queue and the worker runs it
+ * after provisioning. Generates DB credentials up front for apps that need one.
+ */
+async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
+  const app = hostingAppCatalog().find((x) => x.slug === slug);
+  if (!app) return;
+  let payload: Record<string, unknown> = { slug };
+  if (app.needsDb) {
+    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
+    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
+    if (!acct) return;
+    const dbName = `${acct.username}_${slug}`.slice(0, 64);
+    const dbUser = dbName.slice(0, 32);
+    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
+    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
+  }
+  void email;
+  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
+}
+
+/**
+ * Begin capturing a renewal payment method for the hosting wizard. A Stripe hosted
+ * Checkout in `mode: "setup"` records a card + off-session mandate WITHOUT charging
+ * anything — the answer to "a $0 first month must still capture a card for renewal".
+ * Returns to the hosting page; the wizard finalises via finalizeCardSetup (shared).
+ */
+export async function startHostingCardSetup(): Promise<{ url?: string; error?: string }> {
+  await assertNotImpersonating();
+  const user = await requireUser();
+  if (!stripeConfigured()) return { error: "Card payments aren’t configured on this installation yet." };
+  try {
+    const url = await createCardSetupSession(user, "/dashboard/hosting");
+    if (!url) return { error: "Stripe didn’t return a setup link. Please try again." };
+    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
+    return { url };
+  } catch (e) {
+    console.error("[hosting] card setup session failed", e);
+    return { error: "We couldn’t start card setup just now. Please try again in a moment." };
+  }
+}
+
