+/**
+ * When the wallet can't cover a hosting renewal but the customer has a saved card,
+ * top the wallet up from the card for the shortfall — the SAME "card funds the
+ * wallet, wallet pays the bill" model worker/billing.ts uses for VPS renewals, and
+ * the answer to the checkout gate that accepts a card-on-file for a $0 first month.
+ *
+ * Reuses the audited off-session primitives verbatim: `chargeSavedCardOffSession`
+ * (two idempotency guards — a permanent per-period marker + Stripe's 24h key) and
+ * `creditOffSessionCharge` (UNIQUE(paymentIntentId) so a replay credits once). On
+ * any failure the wallet is left untouched and the caller falls through to the
+ * existing wallet-only grace/suspend path — a card wobble never suspends anyone
+ * early. Returns the wallet balance to price the renewal decision against.
+ */
+async function topUpHostingFromCard(
+  acct: { id: string; expiresAt: Date | null; primaryDomain: string; user: { id: string; email: string; name: string | null; balanceCents: number; stripeCustomerId: string | null; stripePaymentMethodId: string | null; cardBrand: string | null; cardLast4: string | null; cardExpMonth: number | null; cardExpYear: number | null } },
+  priceCents: number,
+): Promise<number> {
+  const user = acct.user;
+  if (canAfford(user.balanceCents, priceCents)) return user.balanceCents;
+  if (!acct.expiresAt || !hasChargeableCard(user)) return user.balanceCents;
+  // Wallet credit first, card for the remainder — identical split to checkout and
+  // the VPS sweep, so the card is only ever asked for what the wallet can't cover.
+  const split = walletSplit({ dueCents: priceCents, balanceCents: user.balanceCents, useWallet: true });
+  if (split.cardCents <= 0) return user.balanceCents;
+  const marker = renewalChargeMarker(acct.id, acct.expiresAt);
+  const idempotencyKey = `nxeon_hostrenew_${acct.id}_${acct.expiresAt.getTime()}_${split.cardCents}`;
+  const cardLabel = cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear }) ?? "your saved card";
+  const result = await chargeSavedCardOffSession({
+    user,
+    amountCents: split.cardCents,
+    description: `Web Hosting renewal: ${acct.primaryDomain}`,
+    marker,
+    idempotencyKey,
+    metadata: { nxeonHostingAccountId: acct.id, nxeonPeriodStart: acct.expiresAt.toISOString(), nxeonKind: "hosting_renewal" },
+  });
+  if (!result.ok) return user.balanceCents; // decline / 3DS / transient — fall through to grace
+  // Credit the wallet with exactly what Stripe took (a replay credits once).
+  await creditOffSessionCharge({
+    userId: user.id,
+    amountCents: result.amountCents,
+    description: `Card payment for ${acct.primaryDomain} hosting renewal (${cardLabel})`,
+    paymentIntentId: result.paymentIntentId,
+  });
+  return user.balanceCents + result.amountCents;
+}
