export type HostingResult = { ok?: boolean; error?: string; accountId?: string };

// The active-ish states that reserve a domain / occupy a node slot.
const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;

/** Least-loaded enabled+online node with account headroom. */
async function scheduleHostingNode(): Promise<{ id: string } | null> {
  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (!nodes.length) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => ({
      node: n,
      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
    })),
  );
  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
  return withRoom.length ? { id: withRoom[0].node.id } : null;
}

/** A free jailed username on the node, derived from the email + random salt. */
async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
  for (let i = 0; i < 8; i++) {
    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
    if (!isValidUnixUsername(name)) continue;
    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
    if (!taken) return name;
  }
  throw new Error("Could not allocate a username — try again.");
}

/**
 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
 * as every other paid path: no spending while impersonating, verified email,
 * wallet charge in the same tx that creates the record. The account starts
 * PENDING; the worker provisioner brings it up (inert until shared hosting is
 * enabled — see worker/hosting.ts).
 */
export async function orderHostingAccount(
  planId: string,
  domain: string,
  termMonthsRaw?: number,
): Promise<HostingResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const name = normalizeHostingDomain(domain);
  if (!name) return { error: "Enter a domain." };
  if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };

  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };

  // One account per domain across ALL customers — same cross-tenant guard as
  // email subscriptions (a shared vhost keys on server_name).
  const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
  if (dupe) {
    return {
      error:
        dupe.userId === user.id
          ? "You already have a hosting account for this domain."
          : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
    };
  }
  // Also reject if this hostname is already someone's subdomain or addon domain
  // (audit HIGH-2: the primary-order guard used to ignore those two tables).
  if (await isHostnameClaimed(name)) {
    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
  }

  const node = await scheduleHostingNode();
  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };

  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
  // claim inside the charge tx succeeds — otherwise (already redeemed by this
  // account/IP, or the promo is off) the account is created at FULL price. We
  // pre-check eligibility only to pick the balance gate: a first-time customer with
  // a $0 balance can still sign up free, a repeat one is gated against full price.
  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
  // product the promo applies to. See firstMonthFreeAppliesTo.
  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
  const campaign = promoCampaignFromCookie(await cookies());
  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
  // ONCE here, frozen onto the account, charged up front and read back at renewal —
  // so displayed === charged === renewed. A malformed term falls back to monthly.
  const term = normalizeProductTerm(termMonthsRaw);
  const annualPct = await annualDiscountPct();
  const fullCharge = termPriceCents(plan.priceCents, term, annualPct);
  // First-month-free must credit EXACTLY ONE MONTH — never zero a whole annual term.
  // `firstMonthCreditCents(fullCharge, term)` returns the full charge for a 1-month
  // term (genuinely free first month, $0) and one month's share for the annual term,
  // so annual + promo = "one month credited, the other 11 months charged".
  const promoCharge = Math.max(0, fullCharge - firstMonthCreditCents(fullCharge, term));
  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
  const anticipated = eligible ? promoCharge : fullCharge;
  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };

  const limits = planLimits(plan);
  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");

  let accountId = "";
  try {
    await db.$transaction(async (tx) => {
      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
      let debitCents = fullCharge;
      let promoClaimId: string | null = null;
      if (promoEnabled) {
        const claim = await claimFirstMonthFree(tx, {
          userId: user.id,
          ipHash,
          serviceType: "HOSTING",
          campaign,
          chargedCents: promoCharge,
        });
        if (claim.claimed) {
          debitCents = promoCharge;
          promoClaimId = claim.id;
        }
      }
      const note = debitCents < fullCharge ? " — First month free" : "";
      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
      // so the customer sees the yearly commitment AND its real per-month rate.
      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
      await debitWallet(tx, user.id, debitCents);
      await tx.walletTransaction.create({
        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
      });
      const acct = await tx.hostingAccount.create({
        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
        // (identical at runtime then — see lib/order.ts's Server create).
        data: {
          userId: user.id,
          hostingNodeId: node.id,
          planId: plan.id,
          username,
          primaryDomain: name,
          status: "PENDING",
          diskQuotaMB: limits.diskGB * 1024,
          maxSites: limits.maxSites,
          maxDatabases: limits.maxDatabases,
          // The term this account was SOLD on, and the annual rate frozen at sale, so
          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
          termMonths: term,
          annualDiscountPct: annualPct,
          expiresAt: addMonths(new Date(), term),
        } as Prisma.HostingAccountUncheckedCreateInput,
      });
      accountId = acct.id;
      // Atomic hostname claim in the SAME tx as the account row. A colliding
      // primaryDomain (another order, or someone's subdomain/addon of the same
      // name racing us past the advisory isHostnameClaimed check) fails here on
      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
    });
  } catch (e) {
    if (isUniqueViolation(e)) {
      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
    }
    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
  }

  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
  revalidatePath("/dashboard/hosting");
  return { ok: true, accountId };
}

