291	  const starts = await db.auditLog.findMany({
292	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
293	    orderBy: { createdAt: "desc" },
294	    take: 200,
295	  });
296	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
297	  if (userIds.length === 0) return 0;
