299	  let adopted = 0;
300	  for (const userId of userIds) {
301	    const user = await db.user.findUnique({ where: { id: userId } });
302	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
303	
304	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
305	    const removed = await db.auditLog.findFirst({
306	      where: { userId, action: CARD_REMOVED },
307	      orderBy: { createdAt: "desc" },
308	    });
309	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
310	
311	    try {
312	      const list = await stripe().paymentMethods.list({
313	        customer: user.stripeCustomerId,
314	        type: "card",
315	        limit: 5,
316	      });
317	      const pm = list.data[0]; // newest first
318	      if (!pm) continue;
319	      await persistCard(userId, user.stripeCustomerId, pm);
320	      await db.auditLog.create({
321	        data: {
322	          userId,
323	          action: "card.adopted",
324	          detail: `${cardDisplayLabel({
325	            brand: pm.card?.brand ?? null,
326	            last4: pm.card?.last4 ?? null,
327	            expMonth: pm.card?.exp_month ?? null,
328	            expYear: pm.card?.exp_year ?? null,
329	          })} (saved at Stripe but never confirmed in the browser)`,
330	        },
331	      });
332	      adopted++;
333	    } catch (e) {
334	      console.error(`[cards] could not adopt card for ${userId}`, e);
335	    }
336	  }
