/** Charge one hosting renewal, CAS-guarded on expiresAt (double-charge guard). */
async function chargeHostingRenewal(
  acct: { id: string; userId: string; primaryDomain: string; expiresAt: Date | null },
  planName: string,
  priceCents: number,
  newExpiry: Date,
): Promise<boolean> {
  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.hostingAccount.updateMany({
        where: { id: acct.id, status: "ACTIVE", expiresAt: acct.expiresAt },
        data: { expiresAt: newExpiry },
      });
      if (advanced.count === 0) throw new AlreadyHandledError(`hosting ${acct.id}`);
      if (priceCents > 0) {
        await debitWallet(tx, acct.userId, priceCents);
        await tx.walletTransaction.create({
          data: { userId: acct.userId, amountCents: -priceCents, description: `Web Hosting renewal: ${planName} for ${acct.primaryDomain}` },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: acct.userId,
            description: `Web Hosting renewal: ${planName} for ${acct.primaryDomain}`,
            status: "PAID",
            period: { start: acct.expiresAt, end: newExpiry },
            lineItems: [{ description: `${planName} — ${acct.primaryDomain}`, qty: 1, unitCents: priceCents, amountCents: priceCents }],
          }),
        });
      }
      await tx.auditLog.create({
        data: { userId: acct.userId, action: "billing.renewed", detail: `hosting ${acct.id} ${acct.primaryDomain} ${money(priceCents)} -> ${ymd(newExpiry)}` },
