/**
 * The one-month first-month-free credit, computed EXACTLY like the server's
 * `firstMonthCreditCents` (kept inline so this client file never imports the
 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
 * single month. The server recomputes the real debit with the same formula, so
 * displayed === charged.
 */
function firstMonthCredit(fullCents: number, months: number): number {
  if (months <= 1) return fullCents;
  return Math.min(fullCents, Math.round(fullCents / months));
}

function Stepper({ step, steps }: { step: number; steps: string[] }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {steps.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

/* -------------------------------------------------------------- wizard --- */

export function HostingDeployWizard({
  plans,
  apps,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  firstMonthFree = false,
  balanceCents,
  hasCard,
  cardLabel,
  stripeReady,
  tempSubdomainBase,
}: {
  plans: WizardPlan[];
  apps: AppOpt[];
  annualDiscountPct?: number;
  firstMonthFree?: boolean;
  balanceCents: number;
  /** A renewal-capable card is already on file (charged off-session at renewal). */
  hasCard: boolean;
  cardLabel: string | null;
  /** Stripe is configured, so we can capture a card at all. */
  stripeReady: boolean;
  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
  tempSubdomainBase: string;
}) {
  // Steps: Install is only shown when there's an app catalog to pick from.
  const hasApps = apps.length > 0;
  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
  const [step, setStep] = useState(0);

  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
  const [domain, setDomain] = useState("");
  const [appSlug, setAppSlug] = useState("");

  // A card the customer just saved via the Stripe round-trip flips this true
  // without a page reload, so the Review step stops asking for one.
  const [savedCard, setSavedCard] = useState(hasCard);

  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [cardBusy, setCardBusy] = useState(false);
  const [cardNote, setCardNote] = useState("");
  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);

  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
  // this token is the server-side guard against a network retry creating a second
  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
  // after a failure reuses it safely (the server clears a FAILED marker).
  const idemRef = useRef<string>("");
  if (!idemRef.current) idemRef.current = makeToken();

  const plan = plans.find((p) => p.id === planId) ?? null;
  const curLabel = steps[step];
  const isLast = step === steps.length - 1;

  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
  const fullTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
  const creditCents = firstMonthFree ? firstMonthCredit(fullTermCents, termMonths) : 0;
  const dueTodayCents = Math.max(0, fullTermCents - creditCents);
  // What the account renews at — the full term price, unchanged by the promo.
  const renewalCents = fullTermCents;
  const perMonthCents = Math.round(fullTermCents / Math.max(1, termMonths));
  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;

  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
  // worth. This mirrors the server gate in placeHostingOrder exactly.
  const renewalMethodOk = savedCard || balanceCents >= renewalCents;

  /* ----- Stripe card round-trip (draft save + restore) ---------------------- */
  useEffect(() => {
    let sid = "";
    try {
      sid = new URLSearchParams(window.location.search).get("card_setup") ?? "";
    } catch {
      /* no URL access */
    }
    if (!sid) return;
    // Pull our draft back so the customer lands where they left off.
    let d: Draft | null = null;
    try {
      const raw = sessionStorage.getItem(DRAFT_KEY);
      sessionStorage.removeItem(DRAFT_KEY);
      if (raw) d = JSON.parse(raw) as Draft;
    } catch {
      d = null;
    }
    if (d) {
      if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
      if (d.termMonths === 1 || d.termMonths === ANNUAL_TERM_MONTHS) setTermMonths(d.termMonths);
      if (d.domainMode === "temp" || d.domainMode === "own") setDomainMode(d.domainMode);
      if (typeof d.domain === "string") setDomain(d.domain);
      if (apps.some((a) => a.slug === d.appSlug)) setAppSlug(d.appSlug);
    }
    setRestoredAfterSetup(true);
    setStep(steps.length - 1); // land on Review
    if (sid === "canceled") {
      setCardNote("Card setup was cancelled — you weren’t charged. Add a card to enable renewals, or use your wallet.");
      return;
    }
    // Finalise the saved card, then reflect it on the Review step.
    (async () => {
      const res = await finalizeCardSetup(sid);
      if (res.ok) {
        setSavedCard(true);
        setCardNote(`Card saved${res.label ? ` — ${res.label}` : ""}. Your renewals will bill to it.`);
      } else {
        setCardNote(res.error ?? "We couldn’t save that card. Try again or use your wallet.");
      }
    })();
    // Mount-only restore.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function saveDraft() {
    try {
      const d: Draft = { step, planId, termMonths, domainMode, domain, appSlug };
      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(d));
    } catch {
      /* storage disabled — the card flow still works, it just won't restore */
    }
  }

  async function addCard() {
    setCardBusy(true);
    setCardNote("");
    saveDraft();
    try {
      const res = await startHostingCardSetup();
      if (res.url) {
        window.location.href = res.url;
        return;
      }
      setCardNote(res.error ?? "We couldn’t start card setup just now. Please try again.");
    } catch {
      setCardNote("We couldn’t start card setup just now. Please try again.");
    } finally {
      setCardBusy(false);
    }
  }

  /* ----- domain validity (client-side friendliness; server re-validates) ---- */
  const domainTrim = domain.trim().toLowerCase();
  const domainLooksValid = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(domainTrim);
  const domainBlocker =
    domainMode === "own" && !domainLooksValid
      ? domainTrim.length === 0
        ? "Enter the domain you want to host, or switch to a free temporary subdomain."
        : "Enter a valid domain (e.g. example.com)."
      : null;

  const canContinue = curLabel === "Domain" ? !domainBlocker : true;
  const canPlace = !!planId && !busy && !domainBlocker;

  async function place() {
    if (!plan) return;
    setBusy(true);
    setError("");
    try {
      const res = await placeHostingOrder({
        planId,
        domain: domainMode === "own" ? domainTrim : undefined,
        termMonths,
        appSlug: appSlug || undefined,
        idempotencyKey: idemRef.current,
      });
      if ("needCard" in res) {
        setCardNote("Add a renewal payment method to continue — a $0 first month still needs a way to bill month two.");
        setStep(steps.length - 1);
        return;
      }
      if ("error" in res) {
        setError(res.error || "Something went wrong. Your wallet was not charged — try again.");
        return;
      }
      try {
        sessionStorage.removeItem(DRAFT_KEY);
      } catch {
        /* ignore */
      }
      window.location.href = `/dashboard/hosting/${res.accountId}`;
      return;
    } catch {
      setError("Something went wrong. Your wallet was not charged — try again.");
    } finally {
      setBusy(false);
    }
  }

  const domainForReview =
    domainMode === "own"
      ? domainTrim || "—"
      : `a free ${tempSubdomainBase} subdomain (connect a real domain anytime)`;
  const appName = apps.find((a) => a.slug === appSlug)?.name ?? "None";

  return (
    <div className="card">
      <Stepper step={step} steps={steps} />

      {restoredAfterSetup && cardNote && (
        <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">{cardNote}</div>
      )}
      {error && <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}

      {/* -------------------------------------------------------- Plan --- */}
      {curLabel === "Plan" && (
        <div>
          <h2 className="mb-1 font-semibold">Choose your plan</h2>
          <p className="mb-4 text-sm text-slate-400">
            Each account is isolated with its own storage, databases and email. Commit longer to pay less per month —
            you can change the term below.
          </p>
          {plans.length === 0 ? (
            <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
          ) : (
            <>
              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {plans.map((p) => {
                  const rec = recommendHostingPlan(p);
                  const selected = planId === p.id;
                  return (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() => setPlanId(p.id)}
                      className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
                        selected ? "!border-brand-400 ring-1 ring-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
                      }`}
                    >
                      {p.featured && (
                        <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
                          Most popular
