                      </div>
                      <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
                      <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
                        <li>{p.diskGB} GB NVMe SSD storage</li>
                        <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
                        <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
                        <li>{p.bandwidthTB} TB bandwidth</li>
