            {firstMonthFree && creditCents > 0 && (
              <Row k="First month free" v={<span className="text-emerald-300">−{money(creditCents)}</span>} />
            )}
            <Row
              k="Due today"
              v={<span className="text-base font-semibold">{money(dueTodayCents)}</span>}
            />
            <Row
              k="Renews"
              v={
                <span className="text-slate-300">
                  {money(renewalCents)} / {termWord}
                </span>
              }
            />
            {balanceCents > 0 && dueTodayCents > 0 && (
              <Row k="Wallet balance" v={<span className="text-slate-300">{money(balanceCents)}</span>} />
            )}
          </dl>

          {firstMonthFree && (
            <p className="mt-3 text-xs text-emerald-300/90">
              <span className="font-semibold">Free first month</span> — {money(dueTodayCents)} today, then {money(renewalCents)}/{termWord} when it renews. The price you sign up at is the price you renew at.
            </p>
          )}

          {/* Renewal payment method — the core money-safety gate. */}
          <div className="mt-5 rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
            <p className="text-sm font-semibold">Renewal payment method</p>
            {renewalMethodOk ? (
              <p className="mt-1 text-xs text-slate-400">
                {savedCard
                  ? `We’ll bill renewals to your card${cardLabel ? ` (${cardLabel})` : " on file"}.`
                  : `Your wallet balance (${money(balanceCents)}) covers your renewal. Renewals are charged from your wallet — add a card anytime for hands-off billing.`}
              </p>
            ) : (
              <>
                <p className="mt-1 text-xs text-amber-300">
                  A {money(dueTodayCents)} first charge still needs a way to bill your renewal ({money(renewalCents)}/{termWord}). Add a card, or top up your wallet to cover a renewal.
                </p>
                {cardNote && <p className="mt-2 text-xs text-slate-400">{cardNote}</p>}
                {stripeReady ? (
                  <button type="button" className="btn-secondary mt-3" disabled={cardBusy} onClick={addCard}>
                    {cardBusy ? "Opening secure checkout…" : "Add a card for renewals"}
                  </button>
                ) : (
                  <p className="mt-2 text-xs text-slate-500">Card payments aren’t configured here yet — top up your wallet to continue.</p>
                )}
              </>
            )}
          </div>
        </div>
      )}

      {/* ------------------------------------------------------ nav row --- */}
      <div className="mt-6 flex items-center justify-between">
        <button type="button" className="btn-ghost" disabled={step === 0} onClick={() => setStep((s) => Math.max(0, s - 1))}>
          ← Back
        </button>
        {!isLast ? (
          <button
            type="button"
            className="btn-primary"
            disabled={!canContinue || plans.length === 0}
            onClick={() => setStep((s) => s + 1)}
          >
            Continue →
          </button>
        ) : (
          <button
            type="button"
            className="btn-primary px-6"
            disabled={!canPlace || !renewalMethodOk}
            onClick={place}
          >
            {busy ? "Placing order…" : dueTodayCents > 0 ? `Place order — ${money(dueTodayCents)} today` : "Place order — $0 today"}
          </button>
        )}
      </div>
      {isLast && !renewalMethodOk && (
        <p className="mt-3 text-xs text-amber-300">Add a renewal payment method above to place your order.</p>
      )}
    </div>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between">
      <dt className="text-slate-400">{k}</dt>
      <dd className="text-right">{v}</dd>
    </div>
  );
}

/** A short URL-safe idempotency token (no external uuid dependency). */
function makeToken(): string {
  try {
    if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID().replace(/-/g, "");
  } catch {
    /* fall through */
  }
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}`;
}

